# -*- coding: utf-8 -*-
"""MANAPRINT — Générateur OPOA (A4 portrait, 15 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa maquette (bannière « OPOA », la montagne, le voilier et ses reflets,
   les quatre cercles du haut B·I·G·O, les deux cercles N du bas, les plages
   et le cadre). RIEN n'a ete redessine, rien ajoute, rien enleve : on se
   contente d'ECRIRE LES NUMEROS dans les six cercles. NE PAS « ameliorer ».

LA REGLE DU JEU : SIX numeros par carton —
   B 1-15 · I 16-30 · G 46-60 · O 61-75 (un chacun, en haut)
   N 31-45 · N 31-45 (DEUX numeros differents, en bas).
   Le crieur sort 1-75.

L'ARC-EN-CIEL EST CARTON PAR CARTON : la planche n'est gravee qu'une fois
   (un seul carton), puis reposee quinze fois, chaque fois dans la couleur de
   SON carton. En noir & blanc on la repose au gris #555555. Les chiffres
   gardent le gris de la maison impose par app.py.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None

